right_code.class:
// Reusing expensive Pattern and using primitive types
import java.util.regex.Pattern;

public class PerformanceTraps {
    // Compiled once and cached in static final field
    private static final Pattern ROMAN = Pattern.compile(
        "^(?=.)M*(C[MD]|D?C{0,3})(X[CL]|L?X{0,3})(I[XV]|V?I{0,3})$"
    );

    public static boolean isRomanNumeral(String s) {
        return ROMAN.matcher(s).matches();
    }

    public static long sum() {
        long sum = 0L; // Primitive long avoids object creation
        for (long i = 0; i <= Integer.MAX_VALUE; i++) {
            sum += i; // Blazing fast: no boxing or heap allocations
        }
        return sum;
    }
}

right_code.call_site:
public class Main {
    public static void main(String[] args) {
        // Order of magnitude faster, zero GC pressure!
        long total = PerformanceTraps.sum();
        System.out.println("Sum calculated efficiently: " + total);
    }
}
